create extension if not exists "pgcrypto";
create type public.app_role as enum ('citizen','pcrn_l1','pcrn_l2','ngo','hospital','police','admin');
create type public.approval_state as enum ('PENDING','APPROVED','REJECTED','SUSPENDED');
create type public.case_status as enum ('SUBMITTED','PENDING_ROUTING','ROUTING','ASSIGNED','ACCEPTED','VERIFICATION','NEEDS_SUPPORT','VERIFIED','NOT_VERIFIED','ORG_PENDING','INTERVENTION','FOLLOW_UP','CLOSED');
create type public.assistance_type as enum ('PCRN','NGO','HOSPITAL','POLICE');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, mobile_number text, dob date, city_district text, state text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles (user_id uuid primary key references auth.users(id) on delete cascade, role app_role not null, is_active boolean not null default false, approval_status approval_state not null default 'PENDING', approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz not null default now());
create table public.organizations (id uuid primary key default gen_random_uuid(), name text unique not null, organization_type assistance_type not null, approval_status approval_state not null default 'PENDING', approved_by uuid references auth.users(id), approved_at timestamptz, created_at timestamptz not null default now());
create table public.responder_profiles (user_id uuid primary key references auth.users(id) on delete cascade, organization_id uuid references public.organizations(id), response_radius_km numeric(5,2) not null default 3 check(response_radius_km in (1,3,5,10)), active boolean not null default false, approved boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members (organization_id uuid references public.organizations(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, member_title text, approved boolean not null default false, created_at timestamptz not null default now(), primary key(organization_id,user_id));
create table public.cases (id uuid primary key default gen_random_uuid(), case_code text unique not null default ('NR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))), reported_by uuid not null references auth.users(id), child_description text not null, latitude numeric(9,6) not null check(latitude between -90 and 90), longitude numeric(9,6) not null check(longitude between -180 and 180), location_label text, emergency_level text not null default 'STANDARD' check(emergency_level in ('STANDARD','URGENT','IMMEDIATE')), status case_status not null default 'SUBMITTED', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.case_evidence (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, storage_path text unique not null, original_name text not null, mime_type text not null, size_bytes bigint not null, uploaded_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.case_assistance (case_id uuid references public.cases(id) on delete cascade, assistance_type assistance_type not null, notes text, status text not null default 'PENDING', created_at timestamptz not null default now(), primary key(case_id,assistance_type));
create table public.case_assignments (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, responder_id uuid not null references auth.users(id), assistance_type assistance_type not null, distance_km numeric(8,2), status text not null default 'OFFERED' check(status in ('OFFERED','ACCEPTED','DECLINED','EXPIRED')), decision_reason text, offered_at timestamptz not null default now(), responded_at timestamptz);
create table public.case_status_history (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, status case_status not null, changed_by uuid references auth.users(id), note text, created_at timestamptz not null default now());
create table public.case_verifications (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, verifier_id uuid not null references auth.users(id), status text not null check(status in ('VERIFIED','NOT_VERIFIED','NEEDS_SUPPORT')), notes text not null, created_at timestamptz not null default now());
create table public.case_escalations (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, requested_by uuid not null references auth.users(id), reason text not null, status text not null default 'OPEN', handled_by uuid references auth.users(id), handled_at timestamptz, created_at timestamptz not null default now());
create table public.case_interventions (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, organization_id uuid references public.organizations(id), updated_by uuid not null references auth.users(id), notes text not null, outcome text, created_at timestamptz not null default now());
create table public.case_followups (id uuid primary key default gen_random_uuid(), case_id uuid not null references public.cases(id) on delete cascade, created_by uuid not null references auth.users(id), scheduled_for timestamptz, notes text not null, outcome text, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, case_id uuid references public.cases(id) on delete cascade, title text not null, body text not null, type text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.availability (id uuid primary key default gen_random_uuid(), responder_id uuid not null references auth.users(id) on delete cascade, starts_at timestamptz not null, ends_at timestamptz not null, available boolean not null default true, check(ends_at>starts_at));
create table public.responder_locations (responder_id uuid primary key references auth.users(id) on delete cascade, latitude numeric(9,6) not null, longitude numeric(9,6) not null, recorded_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create index cases_reported_by_idx on public.cases(reported_by); create index cases_status_idx on public.cases(status); create index assignment_case_status_idx on public.case_assignments(case_id,status); create index notifications_user_idx on public.notifications(user_id,created_at desc); create index audit_entity_idx on public.audit_logs(entity_type,entity_id);
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_touch before update on public.profiles for each row execute function public.touch_updated_at(); create trigger cases_touch before update on public.cases for each row execute function public.touch_updated_at(); create trigger responders_touch before update on public.responder_profiles for each row execute function public.touch_updated_at();

create or replace function public.distance_km(lat1 numeric, lon1 numeric, lat2 numeric, lon2 numeric) returns numeric language sql immutable as $$ select 6371 * 2 * asin(sqrt(power(sin(radians(lat2-lat1)/2),2)+cos(radians(lat1))*cos(radians(lat2))*power(sin(radians(lon2-lon1)/2),2))) $$;
create or replace function public.route_case(p_case_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare c record; a record; d numeric; begin select * into c from cases where id=p_case_id; update cases set status='ROUTING' where id=p_case_id and status='PENDING_ROUTING'; for a in select rp.user_id, up.role, rl.latitude, rl.longitude, rp.response_radius_km, ca.assistance_type from case_assistance ca join user_roles up on (lower(up.role::text)=lower(ca.assistance_type::text) or (ca.assistance_type='PCRN' and up.role in ('pcrn_l1','pcrn_l2'))) join responder_profiles rp on rp.user_id=up.user_id join responder_locations rl on rl.responder_id=rp.user_id where ca.case_id=p_case_id and rp.approved and rp.active and up.is_active and up.approval_status='APPROVED' and exists(select 1 from availability av where av.responder_id=rp.user_id and av.available and now() between av.starts_at and av.ends_at) order by distance_km(c.latitude,c.longitude,rl.latitude,rl.longitude) limit 1 loop d:=distance_km(c.latitude,c.longitude,a.latitude,a.longitude); if d<=a.response_radius_km then insert into case_assignments(case_id,responder_id,assistance_type,distance_km) values(p_case_id,a.user_id,a.assistance_type,d); insert into notifications(user_id,case_id,title,body,type) values(a.user_id,p_case_id,'New case available','A nearby human-verification request is available.','CASE_ASSIGNMENT'); end if; end loop; end $$;

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.responder_profiles enable row level security; alter table public.organizations enable row level security; alter table public.organization_members enable row level security; alter table public.cases enable row level security; alter table public.case_evidence enable row level security; alter table public.case_assistance enable row level security; alter table public.notifications enable row level security; alter table public.case_assignments enable row level security; alter table public.case_status_history enable row level security; alter table public.case_verifications enable row level security; alter table public.case_escalations enable row level security; alter table public.case_interventions enable row level security; alter table public.case_followups enable row level security; alter table public.availability enable row level security; alter table public.responder_locations enable row level security; alter table public.audit_logs enable row level security;
create policy profiles_self on public.profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy roles_self on public.user_roles for select using(user_id=auth.uid()); create policy responder_self on public.responder_profiles for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy organization_visible on public.organizations for select using(approval_status='APPROVED' or exists(select 1 from organization_members m where m.organization_id=id and m.user_id=auth.uid())); create policy membership_self on public.organization_members for select using(user_id=auth.uid()); create policy cases_citizen on public.cases for select using(reported_by=auth.uid() or exists(select 1 from case_assignments a where a.case_id=id and a.responder_id=auth.uid())); create policy cases_insert on public.cases for insert with check(reported_by=auth.uid()); create policy evidence_permitted on public.case_evidence for select using(uploaded_by=auth.uid() or exists(select 1 from cases c where c.id=case_id and c.reported_by=auth.uid())); create policy evidence_insert on public.case_evidence for insert with check(uploaded_by=auth.uid() and exists(select 1 from cases c where c.id=case_id and c.reported_by=auth.uid())); create policy assistance_permitted on public.case_assistance for select using(exists(select 1 from cases c where c.id=case_id and c.reported_by=auth.uid())); create policy assistance_insert on public.case_assistance for insert with check(exists(select 1 from cases c where c.id=case_id and c.reported_by=auth.uid())); create policy notifications_self on public.notifications for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy assignments_self on public.case_assignments for select using(responder_id=auth.uid()); create policy assignments_update_self on public.case_assignments for update using(responder_id=auth.uid()) with check(responder_id=auth.uid()); create policy history_permitted on public.case_status_history for select using(exists(select 1 from cases c where c.id=case_id and c.reported_by=auth.uid())); create policy history_insert_self on public.case_status_history for insert with check(changed_by=auth.uid()); create policy verification_self on public.case_verifications for select using(verifier_id=auth.uid()); create policy verification_insert_self on public.case_verifications for insert with check(verifier_id=auth.uid()); create policy escalation_self on public.case_escalations for select using(requested_by=auth.uid()); create policy escalation_insert_self on public.case_escalations for insert with check(requested_by=auth.uid()); create policy intervention_self on public.case_interventions for select using(updated_by=auth.uid()); create policy intervention_insert_self on public.case_interventions for insert with check(updated_by=auth.uid()); create policy followup_self on public.case_followups for select using(created_by=auth.uid()); create policy followup_insert_self on public.case_followups for insert with check(created_by=auth.uid()); create policy availability_self on public.availability for all using(responder_id=auth.uid()) with check(responder_id=auth.uid()); create policy location_self on public.responder_locations for all using(responder_id=auth.uid()) with check(responder_id=auth.uid()); create policy audit_self on public.audit_logs for select using(actor_id=auth.uid()); create policy audit_insert_self on public.audit_logs for insert with check(actor_id=auth.uid());
insert into storage.buckets(id,name,public) values('case-evidence','case-evidence',false) on conflict(id) do update set public=false;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='cases') then alter publication supabase_realtime add table public.cases; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='case_assignments') then alter publication supabase_realtime add table public.case_assignments; end if; if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications') then alter publication supabase_realtime add table public.notifications; end if; end $$;